items=[
('ORTHO32','ORTHO32','Deterministic processor architecture','Active','SystemVerilog scalar pipeline, TLA+ specifications, Lean 4 developments, and a matrix-oriented instruction extension.','Predictable execution and explicit architectural state transitions.','FPGA and ASIC paths are under development. Published proofs concern their formal models; this site does not certify fabricated silicon or guarantee every AI workload completes in 768 cycles.'),
('ortho32-host','ORTHO Host','Windows host runtime','Active','C#/.NET 8 Worker Service with named-pipe IPC, a capability broker, routing, and service registration.','A host boundary for device, build, and inference services.','Repository implementation and documentation are available. No independent production, security, or hardware certification is asserted here.'),
('ortho32-api','ORTHO API','REST bridge to the host','Active','Python FastAPI bridge to ORTHOHost via named-pipe IPC.','A versioned service interface for clients.','Requires the host service. Public code is not evidence of a deployed production API or verified end-to-end hardware integration.'),
('ortho32-sdk-java','ORTHO Java SDK','JVM developer interface','Active','Typed Java APIs for devices, tensor jobs, execution traces, and verification results, with a simulator transport.','Stable application-facing interfaces over the ORTHO system contracts.','Simulator tests do not establish FPGA or ASIC performance. Hardware transport support must be checked against the current project documentation.'),
('ortho32-mcp','ORTHO MCP','Tool protocol server','Active','An AWK stdio MCP server with explicit JSON-RPC method dispatch.','A compact tool surface for ORTHO clients.','The current README describes an AWK implementation. This is not a claim of broad IDE compatibility or independent security certification.'),
('ortho32-ai-gateway','ORTHO AI Gateway','Inference routing core','Active','M/MUMPS routines implementing request state, routing, provider calls, streaming events, IPC, and usage records.','An explicit inference request path across the ORTHO stack.','The public README describes the current M/MUMPS core. Website chat is a separate, restricted local-model gateway; it does not expose administrative tools.'),
('ortho32-desktop','ORTHO Desktop','Native desktop interface','Active','Swift on Windows with OpenSwiftUI, Win32/Direct2D, a routing shell, and ORTHOMessages.','A user interface that communicates through ORTHOHost rather than directly with hardware.','Integration depends on host services and Windows components. Public source does not imply a finished installer or validated hardware product.'),
('ortho32-isolation','ORTHO Isolation','Hardware-separated isolation design','Concept','A layered design for root of trust, a minimal hypervisor, hardware data plane, formal isolation, and signed control commands.','Separate tenant workloads from security-critical management functions.','Architecture and proof materials require independent assessment. No completed security evaluation or deployed isolation guarantee is claimed.'),
('sov-kernel-monster','Sovereign Kernel','Compute kernel development','Active','Fortran 2018 and MLIR-oriented kernel work targeting ARM64 SVE2, x86 AVX-512, and PTX.','Explicit compute paths with accompanying formal-method and attestation materials.','Claims in repository documentation have not been independently recompiled or benchmarked as part of this website update.'),
('jacobian-formal','Jacobian Formal','Algebraic formalization research','Scaffold','Lean 4 and Mathlib infrastructure for formal derivatives, Jacobian matrices, and related algebraic obligations.','Investigate formal components of the Jacobian Conjecture.','The README calls this partially verified infrastructure. This page does not claim a proof of the general Jacobian Conjecture.'),
('liquidlean','LiquidLean','Refinement-type research framework','Active','m4 templates, Higher-Order Constraints, Liquid Haskell, and Haskell implementation work.','Explore constraint systems and polynomial algebra with explicit proof obligations.','Research status is determined by the current obligations and audits. No general resolution of an open conjecture is claimed by this website.'),
('liquid-order','LiquidOrder','Higher-order refinement engine','Active','LCF-style proof certificates, predicate ordering, fixed-point reasoning, and a preregistered research protocol.','Keep theorem construction controlled while exploring proof-producing automation.','Conditional theorems and empirical tracks have separate scope. Planned or gated experiments are not completed results.'),
('dmz-f2-decomposition','DMZ over F₂','Characteristic-two formalization','Active','Lean 4 and Mathlib formalization work on an algebraic characteristic-two reduction.','Study the stated algebraic construction with machine-checkable definitions.','A characteristic-two construction does not by itself establish the full analytic DMZ theorem or physical black-hole entropy predictions.'),
('carry-agent','CARRY','Finite-state agent runtime','Active','Rust execution with a Prolog logic kernel and braid-based transition tracking.','Explicit state progression and transition evidence.','Formal or topological descriptions do not establish security or correctness for arbitrary agent actions.'),
('foundry-intel','Foundry Intel','Verification and policy tooling','Active','Proof-lab, policy, agent-runtime, and append-only record tooling.','Organize obligations and execution evidence in a documented workflow.','Public repository claims are scoped to their stated artifacts. This website does not certify every component or claim external accreditation.'),
('snapkitty-research-labs','Research Labs','Research documentation','Active','Quantum-computing, formal-verification, AI-architecture, and governance research materials.','Publish research directions and technical records within the holdings portfolio.','Listed as a holdings research repository. The trust website and its deployment remain separate from SnapKitty infrastructure.'),
('sovereign-bio-resonance','Bio-Resonance','Computational research specification','Concept','A genomic density-operator framework and simulation-oriented modules for research.','Explore the mathematical and computational specification.','Conceptual research only on this website. No clinical validation, diagnostic accuracy, therapeutic efficacy, or regulatory approval is claimed.'),
('cpsc-qft','CPSC','Conservation-preserving compiler','Preprint','Symmetry admission, translation-orbit checks, Trotter factors, a schedule digest, Q# emission, and a Lean commutation development.','Constrain a periodic transverse-field Ising schedule before emission.','A lattice-model compiler study, not a continuum φ⁴ scattering amplitude. A schedule digest binds content; it is not hardware certification.'),
('unlambda-idris-spark','Unlambda','Language-runtime verification scaffold','Scaffold','ATS interfaces, Idris proofs, and SPARK bounded-allocation work.','Build explicit semantics, typed boundaries, and verification gates.','The published scaffold is not a compiler-certified complete Unlambda runtime or a verified generational slot-map heap.')]
projects=[]
for slug,title,what,status,approach,problem,scope in items:
 snapshot=Path('.local/review')/(slug+'.json'); data=json.loads(snapshot.read_text(encoding='utf-8')) if snapshot.exists() else {}
 source=data.get('url',f'https://github.com/AHMADALIPARR/{slug}')
 license_text=data.get('LICENSE','')
 if 'TRI-LICENSE' in license_text: license_label='BSL / AGPL / MPL — see terms'
 elif license_text.startswith('MIT License'):license_label='MIT'
 elif 'GNU AFFERO' in license_text:license_label='AGPL — see terms'
 elif 'Sovereign Source License' in license_text:license_label='Sovereign Source v3'
 elif slug=='unlambda-idris-spark':license_label='Proprietary; source visible'
 elif slug=='cpsc-qft':license_label='CPSC ESCL / AGPL — see terms'
 else:license_label='Not specified in root'
 projects.append(dict(slug=slug,title=title,what=what,status=status,approach=approach,problem=problem,scope=scope,source=source,license=license_label,license_url=source+('/blob/main/LICENSE' if license_text or slug in ('cpsc-qft','unlambda-idris-spark') else '#readme'),docs=source+'#readme'))
Path('content').mkdir(exist_ok=True);Path('content/projects.json').write_text(json.dumps(projects,ensure_ascii=False,indent=2)+'\n',encoding='utf-8')

